//! 🧭️ Structured instructions retain bounded planning and paid label retirement on the actual original Core.
use super::*;
pub(crate) enum OriginalControlPlan{Transfer(Transfer),Table{pc:usize,count:usize,index:usize,selector:usize,depth:usize}}
pub(super) struct ControlAdmission{pub executed:bool,pub plan:Option<OriginalControlPlan>}
pub(super) enum ControlProgress{Pending,Executed,Complete{parameter_return:bool}}
pub(crate) struct Transfer{keep:usize,height:usize,start:usize,count:usize,copied:usize,pc:usize,parameter_return:bool}
impl OriginalControlPlan{
 pub(super) fn advance(&mut self,machine:&mut Machine,module:&CoreModule,cx:&mut StepContext<'_>)->Result<ControlProgress,OriginalTurnFailure>{
  match self{
   Self::Table{pc,count,index,selector,depth}=>{
    let body=body(module,machine)?;while *index<=*count{let mut next=*pc;let value=unsigned(body,&mut next)?;if !charge(cx,next-*pc+4*size_of::<usize>(),0,0)?{return Ok(ControlProgress::Pending)}if *index==*selector||*index==*count&&*selector>=*count{*depth=value}*pc=next;*index+=1;}
    if let Some(plan)=transfer(machine,*depth,true,true,cx)?{machine.values.pop();*self=Self::Transfer(plan);Ok(ControlProgress::Executed)}else{Ok(ControlProgress::Pending)}
   },
   Self::Transfer(plan)=>{
    if plan.copied<plan.count{let width=size_of::<Value>();let count=(plan.count-plan.copied).min(cx.retained_grant().maximum_copy_bytes.saturating_sub(size_of::<usize>())/width);if count==0||!charge(cx,count*width+size_of::<usize>(),0,0)?{return Ok(ControlProgress::Pending)}machine.values.copy_within(plan.start+plan.copied..plan.start+plan.copied+count,plan.height+plan.copied);plan.copied+=count;return Ok(ControlProgress::Pending)}
    let frame=machine.frames.last_mut().ok_or_else(||refused("Core original control retirement has no frame"))?;
    if frame.controls.len()>plan.keep{let control=frame.controls.last_mut().unwrap();if release_vector(&mut control.branch_types,cx)?||release_vector(&mut control.result_types,cx)?{return Ok(ControlProgress::Pending)}if charge(cx,size_of::<ControlFrame>(),0,0)?{frame.controls.pop();}return Ok(ControlProgress::Pending)}
    if !charge(cx,size_of::<Self>()+2*size_of::<usize>(),0,0)?{return Ok(ControlProgress::Pending)}machine.values.truncate(plan.height+plan.count);frame.pc=plan.pc;Ok(ControlProgress::Complete{parameter_return:plan.parameter_return})
   }
  }
 }
}
pub(super) fn admit(module:&CoreModule,machine:&mut Machine,opcode:u8,mut pc:usize,cx:&mut StepContext<'_>)->Result<Option<ControlAdmission>,OriginalTurnFailure>{
 let body=body(module,machine)?;let frame=machine.frames.last().unwrap();
 let plan=match opcode{
  0x02..=0x04=>{
   let shape=shape(body,&mut pc,&module.types)?;let parameters=shape.parameters();let results=shape.results();let conditional=opcode==0x04;let condition=if conditional{match machine.values.last(){Some(Value::I32(value))=>*value!=0,_=>return Err(refused("Core original if requires its i32 condition").into())}}else{true};let available=machine.values.len().checked_sub(usize::from(conditional)).ok_or_else(||refused("Core original block has no condition operand"))?;let height=available.checked_sub(parameters.len()).ok_or_else(||refused("Core original block parameters underflow its stack"))?;types(&machine.values[height..available],parameters)?;
   let bounds=match module.functions.get(frame.function as usize){Some(FunctionDecl::Defined{controls,..})=>controls.get(&(frame.pc)).copied(),_=>None}.ok_or_else(||refused("Core original block has no actual control bounds"))?;
   if !condition&&bounds.else_pc.is_none(){types(&machine.values[height..available],results)?;if !charge(cx,size_of::<Value>()+size_of::<usize>(),0,0)?{return Ok(None)}machine.values.truncate(available);machine.frames.last_mut().unwrap().pc=bounds.end_pc+1;return Ok(Some(ControlAdmission{executed:true,plan:None}))}
   let kind=match opcode{0x02=>ControlKind::Block,0x03=>ControlKind::Loop,_=>ControlKind::If};let branch=if kind==ControlKind::Loop{parameters}else{results};let type_bytes=bytes_for::<ValueType>(branch.len()+results.len())?;let old=frame.controls.capacity();let grow=old==frame.controls.len();let capacity=frame.controls.len()+1;let birth=if grow{bytes_for::<ControlFrame>(capacity)?}else{0};let release=if grow{bytes_for::<ControlFrame>(old)?}else{0};let relocation=if grow{bytes_for::<ControlFrame>(frame.controls.len())?}else{0};if !charge(cx,type_bytes+relocation+size_of::<ControlFrame>()+size_of::<Value>(),type_bytes+birth,release)?{return Ok(None)}
   let mut branch_types=Vec::with_capacity(branch.len());branch_types.extend_from_slice(branch);let mut result_types=Vec::with_capacity(results.len());result_types.extend_from_slice(results);if conditional{machine.values.pop();}let frame=machine.frames.last_mut().unwrap();if grow{let mut controls=Vec::with_capacity(capacity);controls.extend(frame.controls.drain(..));frame.controls=controls;}frame.controls.push(ControlFrame{kind,start_pc:pc,end_pc:bounds.end_pc,stack_height:height,branch_types,result_types});frame.pc=if !condition{bounds.else_pc.unwrap()+1}else{pc};return Ok(Some(ControlAdmission{executed:true,plan:None}))
  },
  0x05|0x0b=>{let index=frame.controls.len().checked_sub(1).ok_or_else(||refused("Core original end requires an actual control label"))?;let control=&frame.controls[index];if opcode==0x05&&control.kind!=ControlKind::If{return Err(refused("Core original else requires its actual if label").into())}transfer_to(machine,index,false,false,cx)?},
  0x0f=>transfer_to(machine,0,false,false,cx)?,
  0x0c|0x0d=>{let depth=unsigned(body,&mut pc)?;if opcode==0x0d{let condition=match machine.values.last(){Some(Value::I32(value))=>*value!=0,_=>return Err(refused("Core original branch requires its i32 condition").into())};if !condition{if !charge(cx,size_of::<Value>()+size_of::<usize>(),0,0)?{return Ok(None)}machine.values.pop();machine.frames.last_mut().unwrap().pc=pc;return Ok(Some(ControlAdmission{executed:true,plan:None}))}}let plan=transfer(machine,depth,true,opcode==0x0d,cx)?;if plan.is_some()&&opcode==0x0d{machine.values.pop();}plan},
  0x0e=>{let count=unsigned(body,&mut pc)?;let selector=match machine.values.last(){Some(Value::I32(value))=>*value as u32 as usize,_=>return Err(refused("Core original branch table requires its i32 selector").into())};if !charge(cx,size_of::<OriginalControlPlan>(),0,0)?{return Ok(None)}return Ok(Some(ControlAdmission{executed:false,plan:Some(OriginalControlPlan::Table{pc,count,index:0,selector,depth:usize::MAX})}))},
  0x1b|0x1c=>{
   let declared=if opcode==0x1c{if unsigned(body,&mut pc)?!=1{return Err(refused("Core original typed select requires one declared result").into())}let first=*body.get(pc).ok_or_else(||refused("Core original select type exceeds its bytecode"))?;pc+=1;Some(value_type(first)?)}else{None};let start=machine.values.len().checked_sub(3).ok_or_else(||refused("Core original select requires three operands"))?;let left=machine.values[start];let right=machine.values[start+1];let condition=match machine.values[start+2]{Value::I32(value)=>value,_=>return Err(refused("Core original select requires an i32 condition").into())};if left.value_type()!=right.value_type()||declared.is_some_and(|ty|ty!=left.value_type()){return Err(refused("Core original select operands differ from their declared type").into())}if !charge(cx,3*size_of::<Value>()+size_of::<usize>(),0,0)?{return Ok(None)}machine.values.truncate(start);machine.values.push(if condition!=0{left}else{right});machine.frames.last_mut().unwrap().pc=pc;return Ok(Some(ControlAdmission{executed:true,plan:None}))
  },
  _=>return Err(refused("Core original structured control instruction is not declared").into())
 };
 Ok(plan.map(|plan|ControlAdmission{executed:true,plan:Some(OriginalControlPlan::Transfer(plan))}))
}
fn transfer(machine:&Machine,depth:usize,branch:bool,pop:bool,cx:&mut StepContext<'_>)->Result<Option<Transfer>,OriginalTurnFailure>{let count=machine.frames.last().ok_or_else(||refused("Core original branch has no actual frame"))?.controls.len();let index=count.checked_sub(depth.checked_add(1).ok_or_else(||refused("Core original branch depth overflow"))?).ok_or_else(||refused("Core original branch depth exceeds its labels"))?;transfer_to(machine,index,branch,pop,cx)}
fn transfer_to(machine:&Machine,index:usize,branch:bool,pop:bool,cx:&mut StepContext<'_>)->Result<Option<Transfer>,OriginalTurnFailure>{let frame=machine.frames.last().unwrap();let control=frame.controls.get(index).ok_or_else(||refused("Core original control target is absent"))?;let target=if branch{&control.branch_types}else{&control.result_types};let available=machine.values.len().checked_sub(usize::from(pop)).ok_or_else(||refused("Core original branch selector is absent"))?;let start=available.checked_sub(target.len()).filter(|start|*start>=control.stack_height).ok_or_else(||refused("Core original control results overlap outer operands"))?;types(&machine.values[start..available],target)?;if !charge(cx,size_of::<Transfer>()+size_of::<Value>(),0,0)?{return Ok(None)}let looping=branch&&control.kind==ControlKind::Loop;Ok(Some(Transfer{keep:if looping{index+1}else{index},height:control.stack_height,start,count:target.len(),copied:0,pc:if looping{control.start_pc}else{control.end_pc+1},parameter_return:control.kind==ControlKind::Function}))}
fn types(values:&[Value],types:&[ValueType])->Result<(),ValueError>{if values.len()!=types.len()||values.iter().zip(types).any(|(value,ty)|value.value_type()!=*ty){return Err(refused("Core original structured control values differ from their declared types"))}Ok(())}
fn body<'a>(module:&'a CoreModule,machine:&Machine)->Result<&'a[u8],ValueError>{match module.functions.get(machine.frames.last().ok_or_else(||refused("Core original control requires its current frame"))?.function as usize){Some(FunctionDecl::Defined{body,..})=>Ok(body),_=>Err(refused("Core original control requires its defined original body"))}}
enum Shape<'a>{Empty,Single(ValueType),Signature(&'a FunctionType)}
impl Shape<'_>{fn parameters(&self)->&[ValueType]{match self{Self::Signature(ty)=>&ty.parameters,_=>&[]}}fn results(&self)->&[ValueType]{match self{Self::Empty=>&[],Self::Single(ty)=>std::slice::from_ref(ty),Self::Signature(ty)=>&ty.results}}}
fn shape<'a>(body:&[u8],pc:&mut usize,types:&'a[FunctionType])->Result<Shape<'a>,ValueError>{let first=*body.get(*pc).ok_or_else(||refused("Core original block type exceeds its bytecode"))?;if first==0x40{*pc+=1;return Ok(Shape::Empty)}if matches!(first,0x7f|0x7e|0x7d|0x7c|0x70|0x6f){*pc+=1;return Ok(Shape::Single(value_type(first)?))}let index=unsigned(body,pc)?;types.get(index).map(Shape::Signature).ok_or_else(||refused("Core original block type index exceeds its module"))}
fn value_type(byte:u8)->Result<ValueType,ValueError>{match byte{0x7f=>Ok(ValueType::I32),0x7e=>Ok(ValueType::I64),0x7d=>Ok(ValueType::F32),0x7c=>Ok(ValueType::F64),0x70=>Ok(ValueType::FuncRef),0x6f=>Ok(ValueType::ExternRef),_=>Err(refused("Core original value type is not declared"))}}

#[cfg(test)]
pub(super) mod tests{
 use super::*;
 use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
 use semio_framework_actor::{RetainedTurnInput,OriginalGuestExecutionBudget};
 use semio_framework_value::RetainedCloneGrant;
 fn clock()->Option<u64>{Some(1000)}
 fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
 fn binary(body:&[u8],callee:Option<&[u8]>)->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();let mut section=|id:u8,data:Vec<u8>|{bytes.extend([id,data.len()as u8]);bytes.extend(data)};section(1,vec![1,0x60,1,0x7f,1,0x7f]);section(3,if callee.is_some(){vec![2,0,0]}else{vec![1,0]});if callee.is_some(){section(4,vec![1,0x70,0,1]);}section(7,vec![1,3,b'r',b'u',b'n',0,0]);if callee.is_some(){section(9,vec![1,0,0x41,0,0x0b,1,1]);}let mut code=vec![if callee.is_some(){2}else{1},body.len()as u8];code.extend_from_slice(body);if let Some(callee)=callee{code.push(callee.len()as u8);code.extend_from_slice(callee);}section(10,code);bytes}

 pub(crate) fn run_original_program(bytes:&[u8],input:i32,expected:i32,name:&str){let module=Arc::new(CoreModule::parse(&bytes).unwrap());let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(93),Generation(6),stock,clock,1000000,1000000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();for _ in 0..100{if owner.resources_ready(){break}epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.advance(&module,cx)}).unwrap();}epoch+=1;assert!(caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.begin_function_step(&module,0,&[Value::I32(input)],cx)}).unwrap());let mut complete=false;
   for _ in 0..2000{epoch+=1;let(call,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:512,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let input=RetainedTurnInput::borrow_original(cx)?;owner.advance_scalar(&module,OriginalGuestExecutionBudget{input,fuel:1,deadline_us:cx.deadline_us()},cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),(heap.requested_bytes,heap.released_bytes));if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{complete=true;break}}
   assert!(complete,"{}",name);assert_eq!(owner.invocation_values(),Some(&[Value::I32(expected)][..]));caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}epoch+=1;caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;owner.close_step(&module,cx)}).unwrap();}assert!(owner.terminal_is_empty());caller.retire(stock);}
 /// 🧭️ Branch planning and label release preserve exact heap receipts while the independent VM produces the same result.
 #[test]
 fn original_structured_control_matches_independent_vm_and_paid_label_retirement(){
  let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
  for row in fixture["cases"].as_array().unwrap(){let body:Vec<u8>=row["body"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect();let callee=row["callee"].as_array().map(|values|values.iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>());let bytes=binary(&body,callee.as_deref());let input=row["args"][0].as_i64().unwrap()as i32;let engine=wasmtime::Engine::default();let oracle=wasmtime::Module::new(&engine,&bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&oracle,&[]).unwrap();let expected=instance.get_typed_func::<i32,i32>(&mut store,"run").unwrap().call(&mut store,input).unwrap();assert_eq!(i64::from(expected),row["expected"].as_i64().unwrap());run_original_program(&bytes,input,expected,row["name"].as_str().unwrap());
  }
 }
}
